import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from directLabels ----
type SeriesPoint_directLabels = { year: number; value: number };
type Series = { name: string; values: SeriesPoint_directLabels[] };

// [name, 2009 share, 2024 share]. The end values are exact and deliberately clustered in three
// groups so the label dodge has real collisions to resolve.
const ENDPOINTS: [string, number, number][] = [
  ['Iceland', 99.9, 99.9],
  ['Norway', 96.0, 98.3],
  ['Costa Rica', 92.5, 97.8],
  ['Brazil', 89.0, 88.9],
  ['New Zealand', 73.5, 87.5],
  ['Austria', 68.0, 86.1],
  ['Denmark', 30.0, 84.4],
  ['Portugal', 45.0, 71.0],
  ['Sweden', 55.0, 68.5],
  ['Canada', 62.0, 68.2]
];

const YEARS = Array.from({ length: 16 }, (_, i) => 2009 + i);

function seeded(seed: number) {
  let state = seed >>> 0;
  return () => ((state = (state * 1664525 + 1013904223) >>> 0) / 4294967296);
}

const renewableShare: Series[] = ENDPOINTS.map(([name, from, to], index) => {
  const random = seeded(index * 977 + 41);
  return {
    name,
    values: YEARS.map((year, step) => {
      const t = step / (YEARS.length - 1);
      const wobble = step === 0 || step === YEARS.length - 1 ? 0 : (random() - 0.5) * 4;
      return { year, value: Math.min(100, Math.max(0, from + (to - from) * t + wobble)) };
    })
  };
});

/** One line per series, each a run of yearly readings sharing a y axis. */
export type Data = { name: string; values: { year: number; value: number }[] }[];

type SeriesPoint = Data[number]['values'][number];

const FONT_SIZE = 11;
const CHAR_WIDTH = 6.3; // approximate advance of the 11px gallery sans, used to size the gutter
const LABEL_GAP = 28; // x offset of the label text from the plot's right edge
const LABEL_STEP = 14; // minimum vertical distance between two labels

const endValue = (s: { values: SeriesPoint[] }) => s.values[s.values.length - 1].value;
const labelOf = (name: string, value: number) => `${name} ${value.toFixed(1)}`;

// Greedy top-down pass, then a bottom-up pass only if the stack overran the plot.
function dodge(desired: number[], step: number, height: number): number[] {
  const order = d3.range(desired.length).sort((a, b) => d3.ascending(desired[a], desired[b]));
  const placed = new Array<number>(desired.length);

  let y = 0;
  for (const i of order) {
    y = Math.max(desired[i], y);
    placed[i] = y;
    y += step;
  }

  if (y - step > height) {
    y = height;
    for (let k = order.length - 1; k >= 0; k--) {
      y = Math.min(placed[order[k]], y);
      placed[order[k]] = y;
      y -= step;
    }
  }
  return placed;
}

export default function DirectlyLabellingLines({
  data = renewableShare,
  width
}: {
  data?: Data;
  width: number;
}) {
  // The right gutter has to hold the widest end label, so the margin follows the data.
  const margin = useMemo(() => {
    const labelWidth = Math.ceil(
      d3.max(data, (s) => labelOf(s.name, endValue(s)).length * CHAR_WIDTH) ?? 0
    );
    return { top: 16, right: LABEL_GAP + labelWidth + 8, bottom: 36, left: 40 };
  }, [data]);

  const height = Math.round(width * 0.6);
  const innerWidth = width - margin.left - margin.right;
  const innerHeight = height - margin.top - margin.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data.flatMap((s) => s.values), (d) => d.year) as [number, number])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data.flatMap((s) => s.values), (d) => d.value) as [number, number])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleOrdinal(data.map((s) => s.name), d3.schemeObservable10),
    [data]
  );

  const series = useMemo(() => {
    const line = d3
      .line<SeriesPoint>()
      .x((d) => x(d.year))
      .y((d) => y(d.value))
      .curve(d3.curveMonotoneX);
    return data.map((s) => ({
      name: s.name,
      path: line(s.values) ?? '',
      anchor: y(endValue(s)),
      value: endValue(s).toFixed(1)
    }));
  }, [data, x, y]);

  const labels = useMemo(() => {
    const placed = dodge(series.map((s) => s.anchor), LABEL_STEP, innerHeight);
    return series.map((s, i) => ({ ...s, y: placed[i] }));
  }, [series, innerHeight]);

  const xTicks: Tick[] = useMemo(
    () =>
      x.ticks(Math.max(2, Math.round(innerWidth / 80))).map((v) => ({
        value: d3.format('d')(v),
        offset: x(v)
      })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Renewable share of electricity for ten countries, 2009 to 2024, with each line labelled in a right-hand gutter"
    >
      <g transform={`translate(${margin.left},${margin.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <text x={-margin.left} y={-4} fill="var(--muted)" fontSize={FONT_SIZE}>
          ↑ Renewable share of electricity (%)
        </text>
        {labels.map((s) => (
          <path
            key={s.name}
            d={s.path}
            fill="none"
            stroke={color(s.name)}
            strokeWidth={1.6}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
        ))}
        {labels.map((s) => (
          <g key={s.name}>
            <circle cx={innerWidth} cy={s.anchor} r={3} fill={color(s.name)} />
            {Math.abs(s.y - s.anchor) > 1 && (
              <path
                d={`M${innerWidth + 5},${s.anchor}H${innerWidth + 12}L${innerWidth + LABEL_GAP - 6},${s.y}H${innerWidth + LABEL_GAP - 3}`}
                fill="none"
                stroke={color(s.name)}
                strokeWidth={1}
                strokeOpacity={0.55}
              />
            )}
            <text
              x={innerWidth + LABEL_GAP}
              y={s.y}
              dy="0.32em"
              fontSize={FONT_SIZE}
              fill={color(s.name)}
            >
              {s.name}
              <tspan fill="var(--muted)"> {s.value}</tspan>
            </text>
          </g>
        ))}
      </g>
    </svg>
  );
}
